UPDATE SCM_ADM_API_M SET API_URL='PKG_DMF0044.P_DMF0044_GET_EXCHANGE_POPUP_SPREAD_TITLE' WHERE UPPER(API_URL)='DMF0044_GET_EXCHANGE_POPUP_SPREAD_TITLE';
