-- 2) PROC_M: PKG한정명 행 (standalone DROP 전 클론). 멱등: 기존 PKG행 DELETE 후 INSERT.
DELETE FROM SCM_ADM_PROC_M WHERE PROC_NM='PKG_DMF0044.P_DMF0044_GET_EXCHANGE_POPUP_SPREAD_TITLE';

